package playbook

// One-way conversion of a Go-native `.play.json` playbook into a Python
// `.play.py` mirror.
//
// The Python reference runtime lists and executes only `.play.py`; it never
// reads `.play.json`. The Go port therefore keeps its native JSON library
// usable from Python by writing a generated `.play.py` beside it. The mirror is
// a conversion, not a second source of truth:
//
//   - it is generated from the same declarative fields the Go runner uses;
//   - the first line is PythonMirrorMarker, so a generated file is refreshed
//     when the JSON changes while a hand-written `.play.py` is never touched;
//   - the `.play.json` stays authoritative on the Go side (ResolveScript
//     prefers it when both extensions exist).

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/shark2202/go_hive/go-hive/internal/atomicfs"
)

// PythonMirrorMarker starts every generated `.play.py` mirror.
const PythonMirrorMarker = "# Generated by go_hive from "

// NativeExportOptions is the native JSON playbook contract reduced to the
// fields the Python mirror needs. It mirrors the JSON accepted by
// run_playbook's native form (internal/colony/playbook_tools.go).
type NativeExportOptions struct {
	Name           string
	SourceName     string
	Description    string
	Concurrency    *int
	PendingSQL     string
	Task           string
	Goal           string
	Profile        string
	Skill          string
	DataColumns    []string
	Retries        int
	Backoff        string
	TimeoutSeconds *float64
	MaxRounds      *int
	Chunk          *int
	CircuitBreaker *float64
}

// ExportNativePython renders the declarative playbook as an equivalent
// `.play.py` script. The generated script uses the same injected API
// (tracker_query / converge / worker / tracker_count) the Python runner gives
// every playbook.
func ExportNativePython(opts NativeExportOptions) (string, error) {
	name := strings.TrimSpace(opts.Name)
	if name == "" {
		return "", fmt.Errorf("native playbook requires a non-empty 'name'")
	}
	if strings.TrimSpace(opts.PendingSQL) == "" {
		return "", fmt.Errorf("native playbook requires 'pending_sql' (the undone ROWS, not COUNT(*))")
	}
	if strings.TrimSpace(opts.Task) == "" {
		return "", fmt.Errorf("native playbook requires a 'task' template")
	}
	backoff := strings.ToLower(strings.TrimSpace(opts.Backoff))
	switch backoff {
	case "", "exp", "linear":
	default:
		return "", fmt.Errorf("native playbook 'backoff' must be 'exp' or 'linear' (got %q)", opts.Backoff)
	}

	concurrency := DefaultPlaybookConcurrency
	if opts.Concurrency != nil {
		concurrency = *opts.Concurrency
	}
	if concurrency < 1 {
		concurrency = 1
	}
	if concurrency > MaxPlaybookConcurrency {
		return "", fmt.Errorf("native playbook 'concurrency'=%d exceeds the maximum %d", concurrency, MaxPlaybookConcurrency)
	}
	maxRounds := 1
	if opts.MaxRounds != nil {
		maxRounds = *opts.MaxRounds
	}
	if maxRounds < 1 {
		return "", fmt.Errorf("native playbook 'max_rounds' must be >= 1")
	}
	chunk := concurrency
	if opts.Chunk != nil {
		if *opts.Chunk < 1 {
			return "", fmt.Errorf("native playbook 'chunk' must be >= 1")
		}
		if *opts.Chunk < chunk {
			chunk = *opts.Chunk
		}
	}
	if opts.TimeoutSeconds != nil && *opts.TimeoutSeconds <= 0 {
		return "", fmt.Errorf("native playbook 'timeout_seconds' must be > 0")
	}

	var b strings.Builder
	b.WriteString(PythonMirrorMarker)
	b.WriteString("playbooks/")
	sourceName := strings.TrimSpace(opts.SourceName)
	if sourceName == "" {
		sourceName = name
	}
	b.WriteString(SanitizeName(sourceName))
	b.WriteString(".play.json — one-way export.\n")
	b.WriteString("# The Python runtime cannot read .play.json. Go rewrites this mirror when\n")
	b.WriteString("# the JSON source changes; edit the .play.json, not this file.\n")
	b.WriteString("meta = {\n")
	fmt.Fprintf(&b, "    \"name\": %s,\n", pythonLiteral(name))
	fmt.Fprintf(&b, "    \"description\": %s,\n", pythonLiteral(opts.Description))
	fmt.Fprintf(&b, "    \"concurrency\": %d,\n", concurrency)
	b.WriteString("}\n\n")
	fmt.Fprintf(&b, "_PENDING_SQL = %s\n", pythonLiteral(opts.PendingSQL))
	fmt.Fprintf(&b, "_TASK = %s\n", pythonLiteral(opts.Task))
	if strings.TrimSpace(opts.Goal) != "" {
		fmt.Fprintf(&b, "_GOAL = %s\n", pythonLiteral(opts.Goal))
	}
	if len(opts.DataColumns) > 0 {
		b.WriteString("_DATA_COLUMNS = (")
		for index, column := range opts.DataColumns {
			if index > 0 {
				b.WriteString(", ")
			}
			b.WriteString(pythonLiteral(column))
		}
		b.WriteString(")\n")
	}
	b.WriteString("\n")
	b.WriteString("def _render(template, row):\n")
	b.WriteString("    out = template\n")
	b.WriteString("    for key, value in row.items():\n")
	b.WriteString("        out = out.replace(\"{\" + key + \"}\", str(value))\n")
	b.WriteString("        out = out.replace(\"{{\" + key + \"}}\", str(value))\n")
	b.WriteString("    return out\n\n")
	b.WriteString("def _data(row):\n")
	if len(opts.DataColumns) == 0 {
		b.WriteString("    return dict(row)\n\n")
	} else {
		b.WriteString("    return {key: row[key] for key in _DATA_COLUMNS if key in row}\n\n")
	}
	b.WriteString("async def run(args):\n")
	b.WriteString("    result = await converge(\n")
	b.WriteString("        pending=lambda: tracker_query(_PENDING_SQL),\n")
	b.WriteString("        dispatch=lambda row, i: worker(\n")
	b.WriteString("            task=_render(_TASK, row),\n")
	if strings.TrimSpace(opts.Goal) != "" {
		b.WriteString("            goal=_render(_GOAL, row),\n")
	}
	if strings.TrimSpace(opts.Profile) != "" {
		fmt.Fprintf(&b, "            profile=%s,\n", pythonLiteral(opts.Profile))
	}
	if strings.TrimSpace(opts.Skill) != "" {
		fmt.Fprintf(&b, "            skill=%s,\n", pythonLiteral(opts.Skill))
	}
	b.WriteString("            data=_data(row),\n")
	fmt.Fprintf(&b, "            retries=%d,\n", opts.Retries)
	if backoff != "" {
		fmt.Fprintf(&b, "            backoff=%s,\n", pythonLiteral(backoff))
	}
	if opts.TimeoutSeconds != nil {
		fmt.Fprintf(&b, "            timeout=%s,\n", pythonFloat(*opts.TimeoutSeconds))
	}
	b.WriteString("        ),\n")
	fmt.Fprintf(&b, "        max_rounds=%d,\n", maxRounds)
	fmt.Fprintf(&b, "        chunk=%d,\n", chunk)
	if opts.CircuitBreaker != nil {
		fmt.Fprintf(&b, "        circuit_breaker=%s,\n", pythonFloat(*opts.CircuitBreaker))
	}
	b.WriteString("    )\n")
	b.WriteString("    result[\"args\"] = args\n")
	b.WriteString("    return result\n")
	return b.String(), nil
}

// EnsureNativePythonMirror writes the generated `.play.py` mirror into
// playbooksDir and reports whether it wrote. A hand-written `.play.py` (one
// without PythonMirrorMarker) is never overwritten: Python's library may
// legitimately hold a different script than the Go-native JSON.
func EnsureNativePythonMirror(playbooksDir, base string, opts NativeExportOptions) (string, bool, error) {
	opts.SourceName = base
	script, err := ExportNativePython(opts)
	if err != nil {
		return "", false, err
	}
	if strings.TrimSpace(playbooksDir) == "" {
		return "", false, fmt.Errorf("no playbooks directory")
	}
	target := filepath.Join(playbooksDir, SanitizeName(base)+".play.py")
	if existing, readErr := os.ReadFile(target); readErr == nil {
		if !bytes.HasPrefix(existing, []byte(PythonMirrorMarker)) {
			return target, false, nil
		}
		if string(existing) == script {
			return target, false, nil
		}
	}
	if err := atomicfs.WriteFile(target, []byte(script), 0o644); err != nil {
		return "", false, err
	}
	return target, true, nil
}

// pythonLiteral renders s as a Python string literal. JSON string syntax is a
// subset of Python's for the escapes Go emits (quotes, backslashes, control
// characters, unicode), and SetEscapeHTML keeps URLs and `<` readable.
func pythonLiteral(s string) string {
	var buf bytes.Buffer
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)
	if err := encoder.Encode(s); err != nil {
		return `""`
	}
	return strings.TrimSuffix(buf.String(), "\n")
}

// pythonFloat renders a float without an exponent for ordinary durations, and
// with Go's shortest round-trippable form otherwise.
func pythonFloat(value float64) string {
	return strconv.FormatFloat(value, 'g', -1, 64)
}
